{
  "headline": "FDA's records trace our supply to plants with OAI and VAI classifications before the shortage posting",
  "headline_cites": ["D24", "D13", "D16", "D17"],
  "sentences": [
    {
      "text": "FDA first posted the dextrose monohydrate shortage on 2022-01-13 and it remains current as of 2026-10-21.",
      "cites": ["E115", "D32"]
    },
    {
      "text": "FDA's OAI classification letter for inspection 975174 at B. Braun US Pharmaceutical Manufacturing LLC (FEI 2021236) is dated 2020-10-22, 448 days before the shortage posting.",
      "cites": ["D24"]
    },
    {
      "text": "FDA inspection 1110899 at Hospira, Inc. (FEI 1021343) ended 2019-11-21, classified VAI, 784 days before the shortage posting.",
      "cites": ["D13"]
    },
    {
      "text": "FDA inspection 1146372 at Bieffe Medital, S.A. (FEI 3005164365) ended 2021-04-22, classified VAI, 266 days before the shortage posting.",
      "cites": ["D16"]
    },
    {
      "text": "FDA inspection 1152417 at B. Braun US Pharmaceutical Manufacturing, LLC (FEI 2021236) ended 2021-08-17, classified VAI, 149 days before the shortage posting.",
      "cites": ["D17"]
    },
    {
      "text": "Corvale East holds 72 bags of 50 g/1000 mL dextrose 250 mL bags at 30.2 per day, providing 2.4 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Transfer 89 bags of 50 g/1000 mL, 250 mL from Corvale General to Corvale East; Corvale General has 16.7 days on hand and can spare 89 bags while keeping two weeks, and Corvale East would reach 5 days.",
      "cites": ["D33"]
    }
  ]
}
